(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const panel=document.querySelector('.psy-chart-panel'),title=panel.querySelector('.panel-title'),actions=document.createElement('div');actions.className='report-buttons';actions.innerHTML='<button type="button" class="text-button" id="p-preview">'+L('Xem báo cáo','View report')+'</button><button type="button" class="text-button" id="p-print">'+L('Xuất PDF','Export PDF')+'</button>';title.append(actions);
const status=document.createElement('p');status.id='p-report-status';status.className='field-help psy-report-status';status.setAttribute('role','status');status.textContent=L('Báo cáo cần hai trạng thái A/B hợp lệ, lưu lượng và tỷ lệ đúng phạm vi, hỗn hợp không vượt bão hòa. Kiểm tra các đầu vào trước khi xuất.','Reports require valid states A/B, flow and fraction within range, and a mixture that is not supersaturated. Check inputs before exporting.');title.after(status);
function isValid(){return ['dry','value','mass','fraction','pressure'].every(k=>{const e=P(k);return e.value.trim()!==''&&e.validity.valid;})&&!!window.HVACPsychroValidity?.valid({points:psyInputs,pressure:P('pressure').value,mass:P('mass').value,fraction:P('fraction').value});}
function ready(){const ok=isValid();P('preview').disabled=P('print').disabled=!ok;P('report-status').hidden=ok;return ok;}
function table(headers,rows){return '<div class="calc-table-scroll"><table class="calc-output-table"><thead><tr>'+headers.map(t=>'<th>'+esc(t)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function prefixIds(node,prefix){node.querySelectorAll('[id]').forEach(el=>{const id=el.id;node.querySelectorAll('[clip-path],[fill]').forEach(ref=>{for(const attr of ['clip-path','fill']){const v=ref.getAttribute(attr);if(v===`url(#${id})`)ref.setAttribute(attr,`url(#${prefix}${id})`);}});el.id=prefix+id;});}
function build(){psyUpdate();if(!ready())return null;document.getElementById('engineering-report')?.remove();const article=document.createElement('article');article.id='engineering-report';const inputs=psyInputs.map((a,i)=>[i?'B':'A',PF(a.t)+' °C',psyNames[a.kind][0],PF(a.value,5)+' '+psyNames[a.kind][1]]);const chart=P('chart').cloneNode(true);chart.removeAttribute('id');chart.classList.add('psy-report-chart');prefixIds(chart,'psy-report-');article.innerHTML='<h1>HVAC Studio · '+L('Báo cáo không khí ẩm','Psychrometric report')+'</h1><p>'+esc(new Date().toLocaleString(en?'en-GB':'vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}))+' · UTC+7</p><h2>'+L('Thông số đầu vào','Input parameters')+'</h2><p>'+L('Áp suất khí quyển','Atmospheric pressure')+': '+PF(+P('pressure').value,3)+' kPa · '+L('Lưu lượng không khí khô','Dry-air mass flow')+': '+PF(+P('mass').value,6)+' kg/s · '+L('Tỷ lệ dòng A','Stream A fraction')+': '+PF(+P('fraction').value)+'%</p>'+table([L('Điểm','Point'),L('Bầu khô','Dry bulb'),L('Thông số thứ hai','Second input'),L('Giá trị','Value')],inputs)+'<h2>'+L('Biểu đồ trạng thái','State chart')+'</h2>'+chart.outerHTML+'<p>'+esc(P('chart-note').textContent)+'</p><h2>'+L('Kết quả A, B và hòa trộn M','States A, B and mixture M')+'</h2>'+P('table').closest('table').outerHTML+'<h2>'+L('Quá trình A → B & hòa trộn','Process A → B & mixing')+'</h2>'+P('process-results').innerHTML+'<h2>'+L('Phương pháp & phạm vi','Method & scope')+'</h2>'+document.querySelector('.method>div').innerHTML+'<p>hvacstudio.vn</p>';article.querySelectorAll('table').forEach(t=>t.classList.add('calc-output-table'));article.querySelectorAll('[id]').forEach(el=>{if(el.id==='p-table')el.removeAttribute('id');});document.body.append(article);return article;}
P('preview').onclick=()=>{const report=build();if(!report)return;document.getElementById('report-dialog')?.remove();const d=document.createElement('dialog');d.id='report-dialog';d.setAttribute('aria-label',L('Xem báo cáo không khí ẩm','Psychrometric report preview'));d.innerHTML='<div class="report-dialog-actions"><button type="button" class="text-button" id="report-close">'+L('Đóng báo cáo','Close report')+' ×</button></div>'+report.innerHTML;prefixIds(d,'preview-');d.querySelector('.report-dialog-actions button').id='report-close';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.showModal();};P('print').onclick=()=>{if(build())window.HVACPrint.run('engineering');};window.HVACPsychroReport={ready,isValid};document.addEventListener('hvac-project-restore',ready);ready();})();
